16,1)\n    RETURN\nEND\n\n\n/*=====================================================\n    2️⃣ Update ControlLichidare\n=====================================================*/\nUPDATE app.ControlLichidare\nSET \n    Status = @IdConfirmat,\n    ModificatDe = @Username,\n    DataModificarii = GETDATE(),\n    BlocatDe = NULL,\n    DataBlocare = NULL\nWHERE \n    Anul = @Anul\n    AND Luna = @Luna\n    AND CodSucursala = @CodSucursala;\n\n\n/*=====================================================\n    3️⃣ Update CalculLichidare\n=====================================================*/\nUPDATE app.CalculLichidare\nSET \n    Status = @IdConfirmat,\n    LastModifiedDate = SYSDATETIMEOFFSET(),\n    LastModifiedBy = @UserId\nWHERE \n    CodSucursala = @CodSucursala\n    AND Anul = @Anul\n    AND Luna = @Luna;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;},{&quot;value&quot;:&quot;[User:Username]&quot;,&quot;name&quot;:&quot;UserName&quot;},{&quot;value&quot;:&quot;[User:UserId]&quot;,&quot;name&quot;:&quot;UserId&quot;}],&quot;OutputTokenName&quot;:null,&quot;ExtractColumns&quot;:null,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}},{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;45c3a157-8bd4-4f78-bfe8-a75fce7a11f8&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;RefreshGrid&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:1,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;ModuleId&quot;:{&quot;IsExpression&quot